const PHONE_S = {x0: 124, y0: 36, x1: 194, y1: 174}; // kits/inserts-mas PHONE29.screen (71 x 139)
const HEART5 = ['.#.#.', '#####', '#####', '.###.', '..#..'];
/** UI-POST's card grammar (its 9 px avatar chip, the poster's name, the words in the record's casing, the heart row)
 *  re-laid for the 71 px screen of v4's S5.03 phone: the kit's own 'phone' size is 216 px wide and can't fit (at 67 px
 *  its name and handle collide). Returns the card's height. k = frames since it landed (3 held open steps). */
const phoneCard = (b: Buf, x: number, y: number, w: number, spec: PostSpec, o: {hearted: boolean; hearts: number; k?: number}) => {
  const lines = pwrap(spec.text, w - 8);
  const h = 15 + lines.length * 10 + 11;
  const k = o.k ?? 99;
  if (k < 0) return h;
  const open = k >= 3 ? 1 : [0.2, 0.5, 0.8][k];
  const hh = Math.max(3, Math.round(h * open)), yy = y + Math.round((h - hh) / 2);
  rect(x, yy, w, hh, b.ink(PAL.N2)); rect(x, yy, w, 1, b.ink(PAL.N4));
  if (open < 1) return h;
  drawAvatar9(b, x + 3, y + 3, spec.who);
  let name = spec.who === 'staff' ? POSTERS.staff.handle : POSTERS[spec.who].name; // the flood: staff accounts
  while (pw(name) > w - 18 && name.includes(' ')) name = name.slice(0, name.lastIndexOf(' ')); // whole words that fit
  pt(b, name, x + 15, y + 4, PAL.P2);
  lines.forEach((l, i) => pt(b, l, x + 4, y + 15 + i * 10, PAL.P1));
  const fy = y + h - 9, col = o.hearted ? PAL.R3 : PAL.N6;
  HEART5.forEach((r, j) => { for (let i = 0; i < 5; i++) if (r[i] === '#') b.set(x + 4 + i, fy + j, col); });
  if (o.hearts > 0) pt(b, String(o.hearts), x + 12, fy - 1, col);
  return h;
};
S5('S5.03', 'C', 'v4 S5.03\'s inserts-mas drawPhoneInsert29 (the true shot: the dark desk, his thumb, the Orb) with post cards in UI-POST\'s grammar on its screen (re-laid here for the 71 px phone: phoneCard): Rima\'s post, then the same words from everyone, newest at the bottom under his thumb, each hearted on the stick\'s tap spots, the counts climbing (the flood)', (fb, k, sh) => {
  const taps = [mk(sh, 'tap1', 28), mk(sh, 'tap2', 43), mk(sh, 'tap3', 58), mk(sh, 'tap4', 73), mk(sh, 'tap5', 88)];
  const base = postSpec(sh, 'a5-29-P1');
  const HEARTS = [1, 2, 4, 16, 99];
  // the thumb runs on the insert's own 15-frame beat (inserts-mas heartTapAt): aligned so its taps land on the stick's
  // tap spots, hovering before the first
  const fThumb = k < taps[0] - 2 ? 4 : k - taps[0] + 30;
  drawPhoneInsert29(fb, {mode: 'true', f: fThumb, screen: (bb) => {
    const W = PHONE_S.x1 - PHONE_S.x0 + 1, H = PHONE_S.y1 - PHONE_S.y0 + 1;
    const scr = new Buf(W, H, PAL.N1);
    const n = 1 + taps.filter((t) => k >= t + 8).length; // Rima's card, then one more 8 f after each heart
    let y = H - 1;
    for (let i = n - 1; i >= 0 && y > 0; i--) {
      const spec: PostSpec = i === 0 ? base : {...base, who: 'staff'};
      const lit = i < taps.length && k >= taps[i];
      const h = phoneCard(new Buf(1, 1, 0), 0, 0, W - 2, spec, {hearted: lit, hearts: 0}); // measure
      y -= h + 2;
      phoneCard(scr, 1, y, W - 2, spec, {hearted: lit, hearts: lit ? HEARTS[i] : 0, k: i > 0 && i === n - 1 ? k - (taps[i - 1] + 8) : undefined});
    }
    for (let yy = 0; yy < H; yy++) for (let xx = 0; xx < W; xx++) bb.set(PHONE_S.x0 + xx, PHONE_S.y0 + yy, scr.get(xx, yy));
  }});
});
