// ================================================================== checks and the ledger
export const missingShots5 = (ids: string[] = SHOTS.map((s) => s.id)) => ids.filter((id) => !DRAW5[id]);
/** what every shot is built from (the shot list and the report print it) */
export const ledger5 = () => SHOTS.map((s) => ({id: s.id, verdict: s.verdict, kind: DRAW5[s.id]?.kind ?? null, st: DRAW5[s.id]?.st ?? 'STICK FALLBACK (no layout)', standin: DRAW5[s.id]?.standin ?? true}));
/** the in-world texts the new art hard-codes, against the lock (the facts owner re-checks a mismatch) */
export const textChecks5 = () => {
  const out: string[] = [];
  const norm = (s: string) => s.replace(/[“”"…]/g, '').replace(/\s+/g, ' ').trim().toLowerCase();
  for (const [id, key] of Object.entries(POST_KEY)) {
    const sh = SHOTS.find((s) => s.lines.some((l) => l.id === id));
    const l = sh?.lines.find((x) => x.id === id);
    if (l && norm(l.text) !== norm(POSTS[key].text)) out.push(`post ${id}: lock "${l.text}" vs POSTS.${key} "${POSTS[key].text}" (the picture draws the lock's words)`);
  }
  const s303 = SHOTS.find((s) => s.id === 'S3.03');
  const blog = (BLOG as unknown as {lines?: string[]}).lines ?? [];
  for (const t of s303?.texts ?? []) if (t.text.length > 30 && !blog.some((b) => norm(b).includes(norm(t.text).slice(0, 30)))) out.push(`blog S3.03: lock text "${t.text}" not found in BLOG.lines`);
  return out;
};
